ee:message.ee:set-payload:
%dw 2.0
output application/xml skipNullOn="everywhere"
---
{
	sfilluminate:{
	    cambio_numero:{
	        cuenta: payload.cuenta,
	        ext_srvc_id: payload.id_servicio_externo,
	        numero_conexion_origen: payload.numero_conexion_origen,
	        numero_conexion_destino: payload.numero_conexion_destino,
	        fecha_inicio: payload.fecha_inicio
	    }
	}
}

%dw 2.0
output application/xml
ns fact http://factcorpws.etb.com/fact
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
---
soapenv#Envelope @("xmlns:fact": fact): {
    soapenv#Header: {},
    soapenv#Body: {
        'fact:CambioNumero': {
            xmlString: write(payload, 'application/xml')
        }
    }
}

%dw 2.0
output application/json  
---
{
  "wsInvokeServiceProvisioningIN": {
    "services": {
      "service_particulars": [
        {
          "subscriber_id": vars.inputBody.cuenta,
          "service": [
            {
              finder: {
              	"external_service_id": vars.inputBody.id_servicio_externo
              	},
              "feature": vars.inputBody.features map {
                "feature_type_name": $.feature_type_name,
                "parameter": $.parameters map {
                  "action": $.action,
                  "parameter_type_name": $.parameter_type_name,
                  "parameter_value": $.parameter_value,
                  "start_date": {
	                  "month": (vars.inputBody.fecha_inicio as Date {format: "dd-MM-yyyy"}).month as String,
	                  "day": (vars.inputBody.fecha_inicio as Date {format: "dd-MM-yyyy"}).day as String,
	                  "year": (vars.inputBody.fecha_inicio as Date {format: "dd-MM-yyyy"}).year as String
	                },
                }
              }
            }
          ]
        }
      ]
    }
  }
}
